            bool flag = true; 
            foreach (var factor in factors) { 
                // if a^((n-1)/q) equal 1 
                if (power(a, (n - 1) / factor, n) == 1) { 
                    flag = false; 
                    break; 
                } 
            } 

            // if all condition satisfy 
            if (flag) 
                return "prime"; 
        } 
        return "probably composite"; 
    } 

